// Hypothesis coefficients only. Not fitted expression-to-flux relationships.
export const referenceGenes=()=>({myc:1,kras:1,krasMutant:false,p53:1,p53Loss:false});
export function geneRates(g){const myc=.5+.5*g.myc,kras=1+.25*(g.kras-1)+(g.krasMutant?.5:0),p53=g.p53Loss?0:g.p53;return {glucose:{transport:myc*kras,processing:myc*kras*1.25/(1+.25*p53),storage:1},glutamine:{transport:myc,processing:myc,storage:1}};}
export function mountGenes(root,onChange){let state=referenceGenes();
 root.innerHTML=`<div class="membrane-header"><div><h2>Cell identity & genes</h2><span class="membrane-subtitle">Explore a hypothesis. Compare every change with a reference.</span></div><span class="version">EXPLORATORY MODEL</span></div><p class="isotope-copy">Start with a cell scenario, adjust a gene, then follow an isotope pulse. Gene effects are illustrative, not calibrated predictions of healthy or cancer cells.</p><div class="isotope-toolbar"><strong>1 · Choose a starting point</strong><button id="gene-normal">Reference cell</button><button id="gene-cancer">Oncogenic example</button></div><p class="isotope-copy" id="gene-summary" role="status"></p><div class="isotope-toolbar"><strong>2 · Adjust genes</strong><span>1× = reference level. Changes apply immediately; the comparison stays at 1×.</span></div><div class="membrane-grid">${[['myc','MYC','Expression','Changes the model’s glucose and glutamine transport and processing.'],['kras','KRAS','Expression','Changes glucose transport and processing. Mutation and expression are separate controls.'],['p53','TP53 / p53','Functional activity','Changes the assumed glucose-processing rate. This is activity, not protein abundance.']].map(([key,title,label,help])=>`<div class="membrane-card"><h3>${title}</h3><p class="membrane-note">${help}</p><label for="gene-${key}">${label} <output id="gene-${key}-value">1.0×</output></label><input id="gene-${key}" type="range" min="0" max="4" step="0.1" value="1" style="width:100%"><div class="range-labels"><span>0×</span><span>Reference 1×</span><span>4×</span></div>${key==='kras'?'<label><input id="gene-kras-mutant" type="checkbox"> Oncogenic variant · hypothetical</label>':key==='p53'?'<label><input id="gene-p53-loss" type="checkbox"> Loss of p53 function</label>':''}</div>`).join('')}</div><p id="gene-rates" class="isotope-copy"></p><div class="isotope-toolbar gene-launch"><strong>3 · Compare isotope uptake</strong><label for="gene-carrier">Tracer</label><select id="gene-carrier"><option value="glucose">¹³C glucose · gene-linked</option><option value="glutamine">¹⁵N glutamine · gene-linked</option></select><button id="gene-run">Start new comparison →</button><a href="#isotope-lab">View current results</a></div><p class="isotope-copy">Starts a fresh paired run for the chosen tracer using the pulse enrichment below (default 99%). Other tracer runs are preserved. Both cells receive the same pulse; only the experiment receives your gene changes.</p><p class="isotope-copy">Currently connected: glucose and glutamine. P-gp and gene effects on cholesterol, S, Cu, Zn, Ca, Fe, Mg and Se are not implemented. Main-cell ATP and mechanics are not driven by these gene controls.</p><details class="tracer-details"><summary>Model assumptions, equations & evidence</summary><p>This is a sensitivity hypothesis, not a reproduced cell line. MYC factor = 0.5 + 0.5 × expression. KRAS factor = 1 + 0.25 × (expression − 1) + 0.5 for the oncogenic variant. Glucose transport = MYC × KRAS; glucose processing = MYC × KRAS × 1.25 / (1 + 0.25 × p53 activity). Glutamine transport and processing = MYC. Effective p53 activity is zero with loss of function. Coefficients are chosen for exploration, not measured or fitted. There are no transcriptional delays, TIGAR/PPP pathways, cell-cycle, apoptosis or tumour-growth dynamics.</p><p>The reference retains baseline rates of 1×. Adjusting genes preserves histories. Starting a new comparison resets only the chosen tracer pair. P-gp needs a separate validated substrate. Unchanged results for other elements do not demonstrate an absence of biological effects.</p><p>Mechanistic context, not coefficient sources: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC3384197/" target="_blank" rel="noopener noreferrer">MYC and glutamine tracing</a>; <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC3472002/" target="_blank" rel="noopener noreferrer">KRAS and glucose metabolism</a>; <a href="https://pubmed.ncbi.nlm.nih.gov/16839880/" target="_blank" rel="noopener noreferrer">p53 / TIGAR</a>.</p></details>`;
 const $=id=>root.querySelector('#'+id);
 function render(){for(const k of ['myc','kras','p53']){$('gene-'+k).value=state[k];$('gene-'+k+'-value').textContent=state[k].toFixed(1)+'×';}$('gene-kras-mutant').checked=state.krasMutant;$('gene-p53-loss').checked=state.p53Loss;$('gene-p53').disabled=state.p53Loss;const r=geneRates(state);$('gene-summary').textContent='Experiment: MYC '+state.myc.toFixed(1)+'× · KRAS '+state.kras.toFixed(1)+'×'+(state.krasMutant?' (oncogenic)':' (WT)')+' · p53 '+(state.p53Loss?'loss of function':state.p53.toFixed(1)+'×')+'. Reference: MYC 1×, KRAS WT 1×, p53 1×.';$('gene-rates').textContent=`Model response: glucose transport ${r.glucose.transport.toFixed(2)}×; glucose processing ${r.glucose.processing.toFixed(2)}×; glutamine ${r.glutamine.transport.toFixed(2)}×. Reference: 1×.`;}
 for(const k of ['myc','kras','p53'])$('gene-'+k).oninput=()=>{state[k]=Number($('gene-'+k).value);render();onChange({...state});};
 $('gene-kras-mutant').onchange=()=>{state.krasMutant=$('gene-kras-mutant').checked;render();onChange({...state});};$('gene-p53-loss').onchange=()=>{state.p53Loss=$('gene-p53-loss').checked;render();onChange({...state});};
 function reset(notify=true){state=referenceGenes();render();if(notify)onChange({...state});}
 $('gene-normal').onclick=()=>reset();$('gene-cancer').onclick=()=>{state={myc:2,kras:1,krasMutant:true,p53:1,p53Loss:true};render();onChange({...state});};$('gene-run').onclick=()=>onChange({...state},true,$('gene-carrier').value);
 render();return {reset,setCarrier(id){if(['glucose','glutamine'].includes(id))$('gene-carrier').value=id;},get:()=>({...state})};
}
